import {esc,num,btn,card,kv,pill} from './visuals.mjs';
import {PLANS,formatTime,comparePlans} from './model.mjs';
import {stamp,STAGES} from './safety-model.mjs';
import {deploymentSummary} from './work-zone.mjs';

export const FUNCTION_NAMES={R1:'Worker safety',R2:'Queue warnings',R3:'Work-zone planning',R4:'Fleet & charging',SYSTEM:'Model data'};
export const functionName=id=>FUNCTION_NAMES[id]||id;
export const SUPPORT_TOOLS={queue:{title:'Queue warnings',tab:'live'},planning:{title:'Work-zone planning',tab:'layout'},fleet:{title:'Fleet & charging',tab:'supervisor'}};
const values=items=>`<div class="support-values">${items.map(([v,l])=>`<div><strong>${esc(v)}</strong><span>${esc(l)}</span></div>`).join('')}</div>`;
export function supportingCard(tab,site,s,st){
  const tool=Object.keys(SUPPORT_TOOLS).find(k=>SUPPORT_TOOLS[k].tab===tab);if(!tool||tool==='planning')return '';
  const config=SUPPORT_TOOLS[tool],modelled=site.id==='CR';let detail='',foot='';
  if(!modelled){detail=`<p>No ${config.title.toLowerCase()} model has been configured for ${esc(site.name)}.</p>`;foot='The Cremorne example is available inside the supporting tool. Its results do not describe this worksite.';}
  else if(tool==='queue'){
    detail=values([[s.feed?`${num(s.queue.length)} m`:'Unknown','Modelled queue'],[s.queue.speed==null?'No command':`${s.queue.speed} km/h`,'Virtual speed sign']])+`<p>VMS: <strong>${esc(s.queue.vms.replace('\n',' / '))}</strong></p>`;
    foot=`Cremorne illustrative model · ${formatTime(480+s.time/60)} model time (${num(s.time/60,1)} min elapsed). Independent of the on-site replay. SCATS historical counts are context, not live queue detection.`;
  }else if(tool==='planning'){
    detail=values([[`Plan ${s.plan}`,PLANS[s.plan].name],[s.traffic.pedestrian.reachable?`+${num(s.traffic.pedestrian.extraMeters)} m`:'No route','Pedestrian diversion'],[s.traffic.bus.reachable?`+${num(s.traffic.bus.extraSeconds/60,1)} min`:'No route','Modelled bus delay']])+`<p>${s.fleet.equipment.items.map(e=>`${e.quantity} ${e.type.toLowerCase()}`).join(' · ')}</p>`;
    foot='Cremorne illustrative planning assumptions. Comparing plans changes queue and equipment models; the controller position and safety configuration remain subject to their own checks.';
  }else{
    const ev=s.fleet.vehicles.find(v=>v.id==='EV-01');
    detail=values([[s.fleet.feasible?'Model feasible':'Review required','Delivery plan'],[`${num(ev.finalKwh,1)} / ${num(st.assumptions.reserveSoc*st.assumptions.battery)} kWh`,'EV finish / required reserve']])+`<p>${esc(s.fleet.issues[0]||'All modelled job, payload and reserve constraints pass.')}</p>`;
    foot='Cremorne illustrative dispatch · 08:00–13:00. A feasible delivery plan does not confirm equipment has arrived or that a site is ready.';
  }
  return `<section class="support-link" aria-label="${config.title} supporting context"><div><span class="eyebrow">SUPPORTING TOOL · ${modelled?'CREMORNE EXAMPLE':'NOT YET MODELLED'}</span><h3>${config.title}</h3>${detail}<small>${foot}</small></div>${btn(`Open ${config.title.toLowerCase()}`,`tool-${tool}`)}</section>`;
}
export function supportingSnapshot(s,st){return {siteId:'CR',siteName:'Cremorne',source:'Illustrative analytical models; not live or calibrated for this worksite',modelTime:formatTime(480+s.time/60),elapsedSeconds:s.time,analysisWindowSeconds:st.assumptions.horizon,independentOfSafetyClock:true,queueWarnings:s.queue,workZonePlanning:{plan:s.plan,traffic:s.traffic,equipment:s.fleet.equipment,comparisons:comparePlans(st.assumptions)},fleetAndCharging:{dispatch:s.fleet,cost:s.cost},boundaries:['No queue notifications are sent to the wearable','Planning changes do not alter the worker safety layout','Fleet feasibility does not confirm arrival or site readiness','No model is configured for Richmond or Southbank']};}

function deploymentCard(d){
  const open=btn('Open work-zone planning','tool-planning','small');
  if(!d)return card('Selected deployment plan','Work-zone planning',`<div class="card-body evidence-deploy empty"><p>No plan has been selected for deployment yet. Compare plans in Work-zone planning, then choose Select for deployment.</p>${open}</div>`);
  const x=d.details,r=x.impacts;
  const summary=d.sentences.map((t,i)=>`<p>${i?esc(t):`<strong>${esc(d.plan)}</strong>${esc(t.slice(d.plan.length))}`}</p>`).join('');
  const facts=[['Location',esc(x.location||'—')],['Window',esc(x.window)],['Closure',`${esc(x.closure)} · ${x.lanes} lane${x.lanes>1?'s':''}`],['Equipment',`${x.equipmentCount} items`],['Congestion',esc(r.congestion)],['Queue / delay',`${r.queueKm.toFixed(1)} km · +${r.delayMin} min`],['Safety risk',esc(r.safety)],['Selected',esc(x.selectedAtDisplay)]].map(([k,v])=>kv(k,v)).join('');
  return card('Selected deployment plan',`${esc(x.source)}${d.changedSinceSelection?' · plan edited after selection; this record shows the selected version':''}`,`<div class="card-body evidence-deploy"><div class="evidence-deploy-summary">${summary}${x.notes?`<p class="evidence-deploy-notes">Notes: ${esc(x.notes)}</p>`:''}${open}</div><div class="evidence-deploy-facts">${facts}</div></div>`);
}

export function evidencePage(s,st,ws,government){
 const events=ws.sites.flatMap(site=>site.events.map(event=>({...event,site}))).sort((a,b)=>b.created-a.created),open=events.filter(e=>e.stage!==3),pending=ws.sites.reduce((n,site)=>n+site.pending.length,0);
 const body=html=>`<div class="card-body">${html}</div>`;
 return `<section class="report-lead"><span class="eyebrow">EVIDENCE & REPORT</span><h2>From alert to action.</h2><p>Review worker events, notification delivery and the response history. Keep the worksite record alongside the assumptions behind each supporting model.</p><div class="actions">${btn('Download scenario JSON','export','primary')}${btn('Export event CSV','csv')}${btn('Print / save PDF','print')}</div></section><div class="metric-grid"><div class="metric"><span class="label">Worker events</span><div class="value">${events.length}</div><span class="detail">Across ${ws.sites.length} demo worksites</span></div><div class="metric"><span class="label">Awaiting closure</span><div class="value ${open.length?'orange':''}">${open.length}</div><span class="detail">Acknowledgement records receipt</span></div><div class="metric"><span class="label">Support completed</span><div class="value">${events.filter(e=>e.type==='support'&&e.stage===3).length}</div><span class="detail">Handover / relief recorded</span></div><div class="metric"><span class="label">Awaiting cloud sync</span><div class="value ${pending?'orange':''}">${pending}</div><span class="detail">Local records retained in this session</span></div></div>${card('Worker event & response history','Local session record · offline changes may not yet appear in the supervisor copy',`<div class="table-scroll"><table><thead><tr><th>Site / event</th><th>Time</th><th>Worker / event</th><th>Notification / receipt</th><th>Response</th><th>Review</th></tr></thead><tbody>${events.length?events.map(e=>`<tr><td><strong>${esc(e.site.name)}</strong><div class="report-event-id">${esc(e.id)}</div></td><td>${stamp(e.created)}</td><td>${esc(e.recipient)}<br><strong>${esc(e.title)}</strong><details class="report-event-detail"><summary>Trigger & history</summary><p>${esc(e.originalBasis||e.basis)}</p><p>Source: ${esc(e.source)} · Configuration v${e.configVersion}</p><ol>${e.audit.map(a=>`<li>${stamp(a.at)} · ${STAGES[a.stage]} · ${esc(a.owner||'Unassigned')} · ${a.acknowledged?'Acknowledged':'Unacknowledged'}${a.result?' · '+esc(a.result):''}</li>`).join('')}</ol></details></td><td>${esc(e.delivery)}<br>${e.acknowledged?'Acknowledged':'Not acknowledged'}</td><td>${STAGES[e.stage]}<br>${esc(e.owner||'Unassigned')}${!e.site.online?'<br><span class="orange">Supervisor copy may be stale</span>':''}</td><td>${btn('Open response','worker-event','small',`data-site="${e.site.id}" data-kind="${e.type}" data-worker="${e.recipient}"`)}</td></tr>`).join(''):'<tr><td colspan="6"><div class="empty">No worker events yet. Start a scenario from Home to follow its response here.</div></td></tr>'}</tbody></table></div>`)}<div class="section-gap">${deploymentCard(deploymentSummary())}</div><div class="evidence-grid two"><article class="evidence-tile"><span class="eyebrow">SUPPORTING SNAPSHOT / CREMORNE</span><h3>Queue warnings</h3>${kv('Modelled queue',s.feed?`${num(s.queue.length)} m`:'Unknown')}${kv('Virtual speed',s.queue.speed==null?'No command':`${s.queue.speed} km/h`)}<p>${esc(s.queue.vms.replace('\n',' / '))}<br>${formatTime(480+s.time/60)} model time · ${num(s.time/60,1)} min elapsed. Independent of the worker replay.</p>${btn('Open queue warnings','tool-queue','small')}</article><article class="evidence-tile"><span class="eyebrow">SUPPORTING SNAPSHOT / CREMORNE</span><h3>Fleet & charging</h3>${kv('Dispatch',s.fleet.feasible?'Model feasible':'Review required')}${kv('Job reassignments',s.fleet.changes.length)}<p>Fixed 08:00–13:00 round trips. Five-year costs use an independent annual mileage assumption.</p>${btn('Open fleet & charging','tool-fleet','small')}</article></div>${card('Supporting model event history','Illustrative Cremorne model · separate from worker safety notifications',`<div class="table-scroll"><table><thead><tr><th>Model time</th><th>Function</th><th>Event</th><th>Receipt</th><th>Evidence</th></tr></thead><tbody>${st.history.length?st.history.slice().reverse().map(e=>`<tr><td>${formatTime(480+e.time/60)}</td><td>${functionName(e.module)}</td><td>${esc(e.title)}</td><td>${st.acknowledged.includes(e.id)?'Acknowledged':'Not acknowledged'}</td><td>${btn('Inspect','inspect','small',`data-id="${esc(e.id)}"`)}</td></tr>`).join(''):'<tr><td colspan="5">No supporting model events recorded.</td></tr>'}</tbody></table></div>`)}<div class="lower-grid">${card('Data sources & provenance','Official road context alongside explicitly simulated operations',body(`<p class="sub">SCATS historical detector counts and Vicmap road geometry provide context. They do not measure the hazards, heart rate, weather or queues in this demonstration.</p><p class="note">Open Worker safety → Site layout → Official road context for the selected junction, data date, attribution and refresh status.</p>${kv('Real road data',government?.scats?'SCATS snapshot + Vicmap roads':'See source status in Site layout')}${kv('Worker inputs','Synthetic scenarios and manual demo actions')}${kv('Queue / planning / fleet','Editable analytical assumptions · Cremorne only')}${kv('Not yet modelled','Richmond and Southbank supporting tools')}${kv('External device control','None')}`))}${card('How to read this report','Session-only evidence · export to retain a copy',body(`<p class="sub">JSON includes all worksite configurations, worker event audits, official-data provenance, both plan comparisons and the current supporting model snapshots. CSV includes worker events and supporting model events.</p><p class="note">Acknowledgement confirms receipt. Event closure requires the corresponding response steps. A feasible fleet plan does not establish site readiness. The prototype does not diagnose health conditions or certify a safe layout.</p><p class="note"><a href="./operating-guide.html" target="_blank" rel="noopener">Read the operating guide</a>. Reloading the page starts a new session. No live camera, physical wearable, calibrated traffic model or external road sign is connected.</p>`))}</div>`;
}
